    tip2: 'KYC के लिए आधार या पैन की कॉपी: आगे और पीछे की फ़ोटो लें, “JPG से PDF” खोलें, एक पेज पर 2 फ़ोटो और असली ID कार्ड साइज़ चुनें, फिर PDF प्रिंट करें या भेजें।',
