    tip5: 'ई-आधार का पासवर्ड: आपके नाम के पहले 4 अक्षर कैपिटल में और जन्म का साल, जैसे SURE1990। बैंक स्टेटमेंट में अक्सर जन्मतिथि या कस्टमर ID होता है; बैंक के ईमेल में लिखा होता है।',
