    tip2: 'KYC-র জন্য আধার বা প্যানের কপি: সামনে আর পেছনের ছবি তুলুন, “JPG থেকে PDF” খুলুন, এক পাতায় 2টি ছবি আর আসল পরিচয়পত্রের মাপ বেছে নিন, তারপর PDF প্রিন্ট করুন বা পাঠান।',
