    tip4: 'WhatsApp, Instagram বা ওয়েবসাইটের জন্য স্লাইড, মেনু কার্ড বা সার্টিফিকেটের ছবি লাগবে? “PDF থেকে JPG”-তে 150 dpi নিন; প্রিন্টের জন্য 300 dpi।',
    tip5: 'ই-আধারের পাসওয়ার্ড: আপনার নামের প্রথম 4টি অক্ষর ক্যাপিটালে আর জন্মের সাল, যেমন SURE1990। ব্যাংক স্টেটমেন্টে প্রায়ই জন্মতারিখ বা কাস্টমার ID থাকে; ব্যাংকের ইমেলে লেখা থাকে।',
    tip6: '“জোরালো” কম্প্রেশন পাতাকে ছবি বানিয়ে দেয়। রেকর্ডের জন্য আসল ফাইল রাখুন, আর চুক্তিপত্র বা ইনভয়েসের মতো ফাইলে, যেখানে লেখা সার্চ করা দরকার, “হালকা” বেছে নিন।',
    inside_title: 'ভেতরে কী হয়?',
    inside_body: 'PDF.js (Mozilla-র তৈরি) প্রতিটি পাতা আপনার ব্রাউজারের ভেতরেই আঁকে। নির্দিষ্ট সাইজে পৌঁছাতে অ্যাপটি কয়েকটি নমুনা পাতায় আলাদা আলাদা স্পষ্টতা (dpi) আর JPEG কোয়ালিটি চেষ্টা করে, মানানসই সেরা সেটিং বাছে, pdf-lib দিয়ে নতুন PDF বানায় আর তারপর তার আসল সাইজ মেপে দেখে। কিছুই কোনো সার্ভারে পাঠানো হয় না।',
