    help_title: 'कसे वापरावे / कामासाठी कल्पना',
    tip1: 'परीक्षा किंवा नोकरीच्या फॉर्ममध्ये “PDF 200 KB पेक्षा कमी” लिहिले आहे? फाइल निवडा, 200 KB दाबा आणि “PDF लहान करा” वर क्लिक करा. SSC, UPSC, NEET, पासपोर्ट, शिष्यवृत्ती, GST आणि इन्कम टॅक्स पोर्टलसाठी उपयोगी.',
    tip2: 'KYC साठी आधार किंवा पॅनची प्रत: पुढच्या आणि मागच्या बाजूचा फोटो काढा, “JPG ते PDF” उघडा, एका पानावर 2 फोटो आणि खऱ्या ओळखपत्राची साइझ निवडा, मग PDF प्रिंट करा किंवा पाठवा.',
    tip3: 'फोनने काढलेला पानाचा फोटो राखाडी किंवा सावलीचा दिसतो? “स्कॅनसारखे” (रंग राहतात) किंवा “ब्लॅक अँड व्हाइट” (सर्वात स्पष्ट अक्षरे, सर्वात लहान फाइल) निवडा.',
    tip4: 'WhatsApp, Instagram किंवा वेबसाइटसाठी स्लाइड, मेन्यू कार्ड किंवा प्रमाणपत्राची इमेज हवी? “PDF ते JPG” मध्ये 150 dpi वापरा; प्रिंटसाठी 300 dpi.',
    tip5: 'ई-आधारचा पासवर्ड: तुमच्या नावाची पहिली 4 अक्षरे कॅपिटलमध्ये आणि जन्माचे वर्ष, उदा. SURE1990. बँक स्टेटमेंटसाठी अनेकदा जन्मतारीख किंवा कस्टमर ID असतो; बँकेच्या ईमेलमध्ये लिहिलेले असते.',
    tip6: '“जोरदार” पद्धत पानांना चित्र बनवते. नोंदीसाठी मूळ फाइल ठेवा, आणि करार किंवा इनव्हॉइससारख्या फाइल्ससाठी, ज्यात मजकूर सर्च व्हायला हवा, “हलकी” पद्धत वापरा.',
    inside_title: 'आत काय होते?',
    inside_body: 'PDF.js (Mozilla ने बनवलेले) प्रत्येक पान तुमच्या ब्राउझरमध्येच काढते. ठरलेल्या साइझपर्यंत पोहोचण्यासाठी ॲप काही नमुना पानांवर वेगवेगळी स्पष्टता (dpi) आणि JPEG क्वालिटी वापरून पाहते, बसणारी सर्वोत्तम सेटिंग निवडते, pdf-lib ने नवी PDF बनवते आणि मग तिची खरी साइझ तपासते. काहीही कोणत्याही सर्व्हरवर पाठवले जात नाही.',
    settings_saved: 'तुमच्या सेटिंग्ज याच डिव्हाइसवर सेव्ह राहतात. तुमच्या फाइल्स कधीच सेव्ह होत नाहीत.'
