    u_compress: 'આ કૉપી નાની કરો',
    u_note: 'પાનાં ચિત્ર તરીકે સેવ થાય છે, એટલે લખાણ સિલેક્ટ નહીં થાય. મૂળ ફાઇલ પણ સાચવી રાખો.',
    u_empty: 'અનલૉક કૉપી અહીં દેખાશે.',
    help_title: 'કેવી રીતે વાપરવું / કામના આઇડિયા',
    tip1: 'પરીક્ષા કે નોકરીના ફોર્મમાં “PDF 200 KB થી ઓછી” લખ્યું છે? ફાઇલ પસંદ કરો, 200 KB દબાવો અને “PDF નાની કરો” પર ક્લિક કરો. SSC, UPSC, NEET, પાસપોર્ટ, સ્કોલરશિપ, GST અને ઇન્કમ ટેક્સ પોર્ટલ માટે કામ આવે છે.',
    tip2: 'KYC માટે આધાર કે પાનની નકલ: આગળ અને પાછળનો ફોટો લો, “JPG થી PDF” ખોલો, એક પાના પર 2 ફોટા અને સાચા ઓળખપત્રની સાઇઝ પસંદ કરો, પછી PDF પ્રિન્ટ કરો કે મોકલો.',
    tip3: 'ફોનથી લીધેલો પાનાનો ફોટો ઝાંખો કે પડછાયાવાળો દેખાય છે? “સ્કેન જેવો” (રંગ રહે છે) અથવા “બ્લેક એન્ડ વ્હાઇટ” (સૌથી સ્પષ્ટ અક્ષર, સૌથી નાની ફાઇલ) પસંદ કરો.',
    tip4: 'WhatsApp, Instagram કે વેબસાઇટ માટે સ્લાઇડ, મેનુ કાર્ડ કે પ્રમાણપત્રની ઇમેજ જોઈએ? “PDF થી JPG” માં 150 dpi વાપરો; પ્રિન્ટ માટે 300 dpi.',
    tip5: 'ઈ-આધારનો પાસવર્ડ: તમારા નામના પહેલા 4 અક્ષર કેપિટલમાં અને જન્મનું વર્ષ, દા.ત. SURE1990. બેંક સ્ટેટમેન્ટમાં ઘણી વાર જન્મતારીખ કે કસ્ટમર ID હોય છે; બેંકના ઇમેઇલમાં લખેલું હોય છે.',
    tip6: '“જોરદાર” રીત પાનાંને ચિત્ર બનાવી દે છે. રેકોર્ડ માટે મૂળ ફાઇલ રાખો, અને કરાર કે ઇન્વૉઇસ જેવી ફાઇલો માટે, જેમાં લખાણ સર્ચ થવું જોઈએ, “હળવી” રીત પસંદ કરો.',
    inside_title: 'અંદર શું થાય છે?',
    inside_body: 'PDF.js (Mozilla નું બનાવેલું) દરેક પાનું તમારા બ્રાઉઝરની અંદર જ દોરે છે. નક્કી સાઇઝ સુધી પહોંચવા ઍપ થોડાં નમૂના પાનાં પર અલગ અલગ સ્પષ્ટતા (dpi) અને JPEG ક્વોલિટી અજમાવે છે, બંધબેસતું સૌથી સારું સેટિંગ પસંદ કરે છે, pdf-lib થી નવી PDF બનાવે છે અને પછી તેની સાચી સાઇઝ તપાસે છે. કંઈ પણ કોઈ સર્વર પર મોકલાતું નથી.',
