    tip6: '“ਤਕੜਾ” ਤਰੀਕਾ ਪੰਨਿਆਂ ਨੂੰ ਤਸਵੀਰ ਬਣਾ ਦਿੰਦਾ ਹੈ। ਰਿਕਾਰਡ ਲਈ ਅਸਲ ਫ਼ਾਈਲ ਰੱਖੋ, ਅਤੇ ਇਕਰਾਰਨਾਮੇ ਜਾਂ ਇਨਵੌਇਸ ਵਰਗੀਆਂ ਫ਼ਾਈਲਾਂ ਲਈ, ਜਿਨ੍ਹਾਂ ਵਿੱਚ ਲਿਖਤ ਸਰਚ ਹੋਣੀ ਚਾਹੀਦੀ ਹੈ, “ਹਲਕਾ” ਤਰੀਕਾ ਚੁਣੋ।',
    inside_title: 'ਅੰਦਰ ਕੀ ਹੁੰਦਾ ਹੈ?',
