    u_warn: 'କେବଳ ନିଜ ଦସ୍ତାବିଜ ପାଇଁ। ପାସୱାର୍ଡ ଆପଣଙ୍କୁ ଜଣାଥିବା ଦରକାର: ଏହି ଟୁଲ୍ ପାସୱାର୍ଡ ଅନୁମାନ କରେ ନାହିଁ କି ଭାଙ୍ଗେ ନାହିଁ।',
