    u_owner: 'ଏହି PDF ପାସୱାର୍ଡ ବିନା ଖୋଲେ, କିନ୍ତୁ ପ୍ରିଣ୍ଟ ବା କପି ବନ୍ଦ ଥାଇପାରେ। ଏହି ବାଧା ବିନା ଗୋଟିଏ କପି ସେଭ୍ କରନ୍ତୁ।',
    u_none: 'ଏହି PDF ଲକ୍ ନାହିଁ: ପାସୱାର୍ଡ ବିନା ଖୋଲେ ଏବଂ କୌଣସି ବାଧା ନାହିଁ।',
    u_cancel_pw: 'ଏବେ ବି ଲକ୍ ଅଛି: ଅନଲକ୍ କରିବାକୁ ପାସୱାର୍ଡ ଲେଖନ୍ତୁ।',
    u_done: 'ଅନଲକ୍ କପି ପ୍ରସ୍ତୁତ ({pages})। ଏହା ପାସୱାର୍ଡ ବିନା ଖୋଲିବ।',
