    tip1: 'ପରୀକ୍ଷା ବା ଚାକିରି ଫର୍ମରେ ଲେଖାଅଛି “PDF 200 KB ରୁ କମ୍”? ଫାଇଲ୍ ବାଛନ୍ତୁ, 200 KB ଦବାନ୍ତୁ ଏବଂ “PDF ଛୋଟ କରନ୍ତୁ” କ୍ଲିକ୍ କରନ୍ତୁ। SSC, UPSC, NEET, ପାସପୋର୍ଟ, ଛାତ୍ରବୃତ୍ତି, GST ଓ ଆୟକର ପୋର୍ଟାଲ୍ ପାଇଁ କାମରେ ଆସେ।',
    tip2: 'KYC ପାଇଁ ଆଧାର ବା ପ୍ୟାନ୍ କପି: ଆଗ ଓ ପଛ ପଟର ଫଟୋ ନିଅନ୍ତୁ, “JPG ରୁ PDF” ଖୋଲନ୍ତୁ, ଗୋଟିଏ ପୃଷ୍ଠାରେ 2ଟି ଫଟୋ ଓ ପ୍ରକୃତ ପରିଚୟ ପତ୍ର ସାଇଜ୍ ବାଛନ୍ତୁ, ତା ପରେ PDF ପ୍ରିଣ୍ଟ କରନ୍ତୁ ବା ପଠାନ୍ତୁ।',
