    tip5: 'ଇ-ଆଧାର ପାସୱାର୍ଡ: ଆପଣଙ୍କ ନାମର ପ୍ରଥମ 4ଟି ଅକ୍ଷର କ୍ୟାପିଟାଲ୍‌ରେ ଓ ଜନ୍ମ ବର୍ଷ, ଯେପରି SURE1990। ବ୍ୟାଙ୍କ ଷ୍ଟେଟମେଣ୍ଟରେ ପ୍ରାୟତଃ ଜନ୍ମ ତାରିଖ ବା କଷ୍ଟମର ID ଥାଏ; ବ୍ୟାଙ୍କର ଇମେଲରେ ଲେଖାଥାଏ।',
    tip6: '“ଜୋରଦାର” ପଦ୍ଧତି ପୃଷ୍ଠାକୁ ଛବି କରିଦିଏ। ରେକର୍ଡ ପାଇଁ ମୂଳ ଫାଇଲ୍ ରଖନ୍ତୁ, ଏବଂ ଚୁକ୍ତିପତ୍ର ବା ଇନଭଏସ୍ ଭଳି ଫାଇଲ୍ ପାଇଁ, ଯେଉଁଠି ଲେଖା ସର୍ଚ୍ଚ ହେବା ଦରକାର, “ହାଲୁକା” ବାଛନ୍ତୁ।',
    inside_title: 'ଭିତରେ କ’ଣ ହୁଏ?',
    inside_body: 'PDF.js (Mozilla ତିଆରି) ପ୍ରତ୍ୟେକ ପୃଷ୍ଠାକୁ ଆପଣଙ୍କ ବ୍ରାଉଜର ଭିତରେ ହିଁ ଆଙ୍କେ। ନିର୍ଦ୍ଦିଷ୍ଟ ସାଇଜ୍‌ରେ ପହଞ୍ଚିବାକୁ ଆପ୍ କିଛି ନମୁନା ପୃଷ୍ଠାରେ ଅଲଗା ଅଲଗା ସ୍ପଷ୍ଟତା (dpi) ଓ JPEG କ୍ୱାଲିଟି ଚେଷ୍ଟା କରେ, ଖାପ ଖାଉଥିବା ସବୁଠୁ ଭଲ ସେଟିଂ ବାଛେ, pdf-lib ରେ ନୂଆ PDF ତିଆରି କରେ ଏବଂ ତା ପରେ ତାର ପ୍ରକୃତ ସାଇଜ୍ ଯାଞ୍ଚ କରେ। କିଛି ବି କୌଣସି ସର୍ଭରକୁ ପଠାଯାଏ ନାହିଁ।',
    settings_saved: 'ଆପଣଙ୍କ ସେଟିଂ ଏହି ଡିଭାଇସ୍‌ରେ ସେଭ୍ ରହେ। ଆପଣଙ୍କ ଫାଇଲ୍ କେବେବି ସେଭ୍ ହୁଏ ନାହିଁ।'
