    gray_opt: 'கருப்பு-வெள்ளை (கிரேஸ்கேல்): இன்னும் சிறியது',
    c_go: 'PDF சுருக்கு',
    c_empty: 'சிறிதாக்கிய PDF முன்பு / பின்பு முன்னோட்டத்துடன் இங்கே தெரியும்.',
    c_ready: 'அளவைத் தேர்வுசெய்து “PDF சுருக்கு” அழுத்துங்கள்.',
    c_already: 'நல்ல செய்தி: இந்த PDF ஏற்கனவே {to}-க்குக் கீழ் உள்ளது ({size}). அப்படியே பதிவேற்றலாம்.',
    c_saved: '{pct}% சிறியது',
    c_settings: '{dpi} dpi · தரம் {q}%',
    c_done_ok: 'முடிந்தது! இது {to}-க்குக் கீழ் உள்ளது, பதிவேற்றத் தயார்.',
    c_done_over: 'இயன்ற அளவு: {size}. பக்கங்களைப் படிக்க முடியாதபடி ஆக்காமல் {to}-க்குக் கீழ் கொண்டுவர முடியவில்லை. பெரிய அளவு, கிரேஸ்கேல் அல்லது PDF-ஐப் பிரித்துப் பாருங்கள்.',
    c_bigger: 'இந்த PDF ஏற்கனவே நன்றாகச் சுருக்கப்பட்டுள்ளது: புதிய நகல் பெரிதாகும் ({size}). உங்கள் அசல் கோப்பையே வைத்திருங்கள்.',
    c_light_ok: 'முடிந்தது! எழுத்து அப்படியே உள்ளது, கோப்பு {to}-க்குக் கீழ்.',
    c_light_over: 'எழுத்து அப்படியே உள்ளது, ஆனால் கோப்பு இன்னும் {to}-க்கு மேல். அளவை எட்ட “வலுவானது” தேர்வுசெய்யுங்கள்.',
    c_light_none: '“லேசானது” இந்த PDF-ஐச் சிறிதாக்க முடியவில்லை. “வலுவானது” தேர்வுசெய்யுங்கள்.',
    c_light_locked: 'இந்த PDF பூட்டப்பட்டுள்ளதால் “லேசானது” அதை மீண்டும் சேமிக்க முடியாது. “வலுவானது” தேர்வுசெய்யுங்கள் (அது கடவுச்சொல் கேட்கும்) அல்லது முதலில் பூட்டை நீக்குங்கள்.',
    c_auto: 'கோப்பைக் குறைந்த இடத்தில் மீண்டும் சேமித்ததே போதுமானதாக இருந்தது, அதனால் பக்கங்கள் படங்களாக மாறவில்லை. எழுத்து தெளிவாக உள்ளது, தேர்ந்தெடுக்கவும் முடியும்.',
    c_low_res: 'அளவுக்குள் கொண்டுவர பக்கங்கள் {dpi} dpi மட்டுமே, அதனால் சிறிய எழுத்துகள் படிக்கக் கடினமாகலாம். “ஒப்பிடு” மூலம் சரிபாருங்கள்; கிரேஸ்கேல் அல்லது பெரிய அளவு உதவும்.',
    c_before: 'முன்பு',
    c_after: 'பின்பு',
    compare: 'முன்பு / பின்பு ஒப்பிடு',
    cmp_hint: 'இரண்டுக்கும் இடையே மாற்றிப் பார்த்து, எழுத்து இன்னும் எளிதாகப் படிக்க முடிகிறதா எனச் சரிபாருங்கள்.',
    c_note_raster: 'இந்த நகலில் எழுத்து படத்தின் ஒரு பகுதி, அதனால் அதைத் தேர்ந்தெடுக்கவோ தேடவோ முடியாது. உங்கள் பதிவுக்காக அசல் கோப்பை வைத்திருங்கள்.',
    i_title: 'படங்களிலிருந்து PDF',
    i_desc: 'JPG அல்லது PNG படங்கள், ஸ்கேன்கள், ஸ்கிரீன்ஷாட்களை ஒரே PDF-இல் சேருங்கள். வரிசையை மாற்றுங்கள், சுழற்றுங்கள், அடையாள அட்டையின் முன்-பின் பக்கங்களை ஒரே பக்கத்தில் அச்சிடுங்கள்.',
