    aim_under: 'ఇప్పటికే {to} కంటే తక్కువ ఉంది. చిన్నది చేయాల్సిన అవసరం లేదు.',
    c_hard: 'చాలా తక్కువ చోటు: ఒక్కో పేజీకి సుమారు {kb} KB మాత్రమే. అక్షరాలు చదవడం కష్టం కావచ్చు. గ్రేస్కేల్, పెద్ద సైజు లేదా PDFను విభజించి చూడండి.',
