    c_light_over: 'టెక్స్ట్ అలాగే ఉంది, కానీ ఫైల్ ఇంకా {to} కంటే ఎక్కువ. సైజుకు చేరడానికి “బలమైనది” ఎంచుకోండి.',
    c_light_none: '“తేలికైనది” ఈ PDFను చిన్నది చేయలేకపోయింది. “బలమైనది” ఎంచుకోండి.',
    c_light_locked: 'ఈ PDF లాక్ అయి ఉంది, కాబట్టి “తేలికైనది” దాన్ని మళ్లీ సేవ్ చేయలేదు. “బలమైనది” ఎంచుకోండి (అది పాస్‌వర్డ్ అడుగుతుంది) లేదా ముందుగా అన్‌లాక్ చేయండి.',
    c_auto: 'ఫైల్‌ను తక్కువ చోటులో మళ్లీ సేవ్ చేయడమే సరిపోయింది, కాబట్టి పేజీలు చిత్రాలుగా మారలేదు. టెక్స్ట్ స్పష్టంగా ఉంది, సెలెక్ట్ చేయవచ్చు.',
    c_low_res: 'సైజులోకి తేవడానికి పేజీలు {dpi} dpi మాత్రమే, కాబట్టి చిన్న అక్షరాలు చదవడం కష్టం కావచ్చు. “పోల్చు”తో చూడండి; గ్రేస్కేల్ లేదా పెద్ద సైజు సాయపడుతుంది.',
