    c_note_raster: 'ఈ కాపీలో టెక్స్ట్ చిత్రంలో భాగం, కాబట్టి దాన్ని సెలెక్ట్ లేదా సెర్చ్ చేయలేరు. మీ రికార్డుల కోసం అసలు ఫైల్‌ను ఉంచుకోండి.',
    i_title: 'ఫోటోల నుండి PDF',
    i_desc: 'JPG లేదా PNG ఫోటోలు, స్కాన్‌లు, స్క్రీన్‌షాట్‌లను ఒకే PDFలో కలపండి. క్రమం మార్చండి, తిప్పండి, గుర్తింపు కార్డు ముందు-వెనుకను ఒకే పేజీలో ప్రింట్ చేయండి.',
