    tip1: 'పరీక్ష లేదా ఉద్యోగ ఫారంలో “PDF 200 KB లోపు” అని ఉందా? ఫైల్ ఎంచుకుని, 200 KB నొక్కి, “PDF చిన్నది చేయి” నొక్కండి. SSC, UPSC, NEET, పాస్‌పోర్ట్, స్కాలర్‌షిప్, GST, ఆదాయపు పన్ను పోర్టల్స్‌కు పనికొస్తుంది.',
    tip2: 'KYC కోసం ఆధార్ లేదా పాన్ కాపీ: ముందు, వెనుక వైపుల ఫోటో తీసి, “JPG నుండి PDF” తెరిచి, ఒక పేజీలో 2 ఫోటోలు, అసలు గుర్తింపు కార్డు సైజు ఎంచుకుని, PDFను ప్రింట్ చేయండి లేదా పంపండి.',
    tip3: 'ఫోన్‌తో తీసిన పేజీ ఫోటో బూడిదరంగుగా లేదా నీడలతో కనిపిస్తోందా? “స్కాన్ లాగా” (రంగు ఉంటుంది) లేదా “నలుపు-తెలుపు” (అత్యంత స్పష్టమైన అక్షరాలు, అతి చిన్న ఫైల్) ఎంచుకోండి.',
    tip4: 'WhatsApp, Instagram లేదా వెబ్‌సైట్ కోసం స్లైడ్, మెనూ కార్డు లేదా సర్టిఫికెట్ చిత్రంగా కావాలా? “PDF నుండి JPG”లో 150 dpi వాడండి; ప్రింట్‌కు 300 dpi.',
    tip5: 'ఇ-ఆధార్ పాస్‌వర్డ్: మీ పేరులోని మొదటి 4 అక్షరాలు ఇంగ్లీష్ క్యాపిటల్స్‌లో + పుట్టిన సంవత్సరం, ఉదా. SURE1990. బ్యాంక్ స్టేట్‌మెంట్‌లకు తరచుగా పుట్టిన తేదీ లేదా కస్టమర్ ID ఉంటుంది; బ్యాంక్ ఈమెయిల్‌లో రాసి ఉంటుంది.',
    tip6: '“బలమైనది” పద్ధతి పేజీలను చిత్రాలుగా మారుస్తుంది. రికార్డుల కోసం అసలు ఫైల్ ఉంచుకోండి; టెక్స్ట్ సెర్చ్ కావాల్సిన ఒప్పందాలు, ఇన్‌వాయిస్‌లకు “తేలికైనది” వాడండి.',
    inside_title: 'లోపల ఏం జరుగుతుంది?',
    inside_body: 'PDF.js (Mozilla తయారు చేసింది) ప్రతి పేజీని మీ బ్రౌజర్‌లోనే గీస్తుంది. ఒక సైజుకు చేరడానికి యాప్ కొన్ని నమూనా పేజీలపై వేర్వేరు స్పష్టత (dpi), JPEG క్వాలిటీలను ప్రయత్నించి, సరిపోయే ఉత్తమ సెట్టింగ్‌ను ఎంచుకుని, pdf-libతో కొత్త PDF తయారు చేసి, తర్వాత దాని అసలు సైజును చెక్ చేస్తుంది. ఏదీ ఏ సర్వర్‌కూ పంపబడదు.',
    settings_saved: 'మీ సెట్టింగ్‌లు ఈ పరికరంలోనే సేవ్ అవుతాయి. మీ ఫైళ్లు ఎప్పుడూ సేవ్ కావు.'
