    aim_under: 'ಈಗಾಗಲೇ {to} ಗಿಂತ ಕಡಿಮೆ ಇದೆ. ಚಿಕ್ಕದಾಗಿಸುವ ಅಗತ್ಯವಿಲ್ಲ.',
    c_hard: 'ತುಂಬಾ ಕಡಿಮೆ ಜಾಗ: ಪ್ರತಿ ಪುಟಕ್ಕೆ ಸುಮಾರು {kb} KB ಮಾತ್ರ. ಅಕ್ಷರ ಓದಲು ಕಷ್ಟವಾಗಬಹುದು. ಗ್ರೇಸ್ಕೇಲ್, ದೊಡ್ಡ ಗಾತ್ರ ಅಥವಾ PDF ಅನ್ನು ಭಾಗ ಮಾಡಿ ನೋಡಿ.',
    c_method: 'ವಿಧಾನ',
    c_strong: 'ಬಲವಾದ: ಗಾತ್ರ ತಲುಪಿ',
    c_strong_d: 'ಫಾರ್ಮ್ ಮತ್ತು ಪೋರ್ಟಲ್‌ಗಳಿಗೆ ಉತ್ತಮ. ಪುಟಗಳು ಚಿತ್ರಗಳಾಗುತ್ತವೆ, ಹಾಗಾಗಿ ಪಠ್ಯ ಆಯ್ಕೆಯಾಗುವುದಿಲ್ಲ.',
