    gray_opt: 'ಕಪ್ಪು-ಬಿಳುಪು (ಗ್ರೇಸ್ಕೇಲ್): ಇನ್ನೂ ಚಿಕ್ಕದು',
    c_go: 'PDF ಚಿಕ್ಕದಾಗಿಸಿ',
