    c_settings: '{dpi} dpi · ಗುಣಮಟ್ಟ {q}%',
    c_done_ok: 'ಆಯಿತು! ಇದು {to} ಗಿಂತ ಕಡಿಮೆ, ಅಪ್‌ಲೋಡ್‌ಗೆ ಸಿದ್ಧ.',
    c_done_over: 'ಸಾಧ್ಯವಾದಷ್ಟು: {size}. ಪುಟಗಳನ್ನು ಓದಲಾಗದಂತೆ ಮಾಡದೆ {to} ಗಿಂತ ಕಡಿಮೆ ಮಾಡಲಾಗಲಿಲ್ಲ. ದೊಡ್ಡ ಗಾತ್ರ, ಗ್ರೇಸ್ಕೇಲ್ ಅಥವಾ PDF ಅನ್ನು ಭಾಗ ಮಾಡಿ ನೋಡಿ.',
    c_bigger: 'ಈ PDF ಈಗಾಗಲೇ ಚೆನ್ನಾಗಿ ಕಂಪ್ರೆಸ್ ಆಗಿದೆ: ಹೊಸ ಪ್ರತಿ ದೊಡ್ಡದಾಗುತ್ತದೆ ({size}). ನಿಮ್ಮ ಮೂಲ ಫೈಲ್ ಅನ್ನೇ ಇಟ್ಟುಕೊಳ್ಳಿ.',
    c_light_ok: 'ಆಯಿತು! ಪಠ್ಯ ಹಾಗೆಯೇ ಇದೆ, ಫೈಲ್ {to} ಗಿಂತ ಕಡಿಮೆ.',
    c_light_over: 'ಪಠ್ಯ ಹಾಗೆಯೇ ಇದೆ, ಆದರೆ ಫೈಲ್ ಇನ್ನೂ {to} ಗಿಂತ ಹೆಚ್ಚು. ಗಾತ್ರ ತಲುಪಲು “ಬಲವಾದ” ಆಯ್ಕೆಮಾಡಿ.',
    c_light_none: '“ಹಗುರ” ಈ PDF ಅನ್ನು ಚಿಕ್ಕದಾಗಿಸಲಾಗಲಿಲ್ಲ. “ಬಲವಾದ” ಆಯ್ಕೆಮಾಡಿ.',
    c_light_locked: 'ಈ PDF ಲಾಕ್ ಆಗಿದೆ, ಹಾಗಾಗಿ “ಹಗುರ” ಅದನ್ನು ಮತ್ತೆ ಉಳಿಸಲಾಗದು. “ಬಲವಾದ” ಆಯ್ಕೆಮಾಡಿ (ಅದು ಪಾಸ್‌ವರ್ಡ್ ಕೇಳುತ್ತದೆ) ಅಥವಾ ಮೊದಲು ಅನ್‌ಲಾಕ್ ಮಾಡಿ.',
    c_auto: 'ಫೈಲ್ ಅನ್ನು ಕಡಿಮೆ ಜಾಗದಲ್ಲಿ ಮತ್ತೆ ಉಳಿಸಿದರೆ ಸಾಕಾಯಿತು, ಹಾಗಾಗಿ ಪುಟಗಳು ಚಿತ್ರಗಳಾಗಲಿಲ್ಲ. ಪಠ್ಯ ಸ್ಪಷ್ಟವಾಗಿದೆ, ಆಯ್ಕೆ ಮಾಡಬಹುದು.',
    c_low_res: 'ಗಾತ್ರಕ್ಕೆ ತರಲು ಪುಟಗಳು {dpi} dpi ಮಾತ್ರ, ಹಾಗಾಗಿ ಸಣ್ಣ ಅಕ್ಷರ ಓದಲು ಕಷ್ಟವಾಗಬಹುದು. “ಹೋಲಿಸಿ” ಮೂಲಕ ಪರೀಕ್ಷಿಸಿ; ಗ್ರೇಸ್ಕೇಲ್ ಅಥವಾ ದೊಡ್ಡ ಗಾತ್ರ ನೆರವಾಗುತ್ತದೆ.',
