    pw_own: 'നിങ്ങളുടെ സ്വന്തം രേഖകൾക്ക് മാത്രം. പാസ്‌വേഡ് ഈ ഉപകരണത്തിൽ മാത്രമേ ഉപയോഗിക്കൂ.',
    c_title: 'PDF ചെറുതാക്കൂ',
    c_desc: 'വെബ്സൈറ്റ് ആവശ്യപ്പെടുന്ന വലുപ്പം തിരഞ്ഞെടുക്കൂ. ആ വലുപ്പത്തിനുള്ളിൽ ഏറ്റവും വ്യക്തമായ പേജുകൾ ലഭിക്കും.',
