    aim_under: 'ഇതിനകം {to}-ൽ താഴെയാണ്. ചെറുതാക്കേണ്ടതില്ല.',
    c_hard: 'വളരെ കുറഞ്ഞ ഇടം: ഓരോ പേജിനും ഏകദേശം {kb} KB മാത്രം. അക്ഷരങ്ങൾ വായിക്കാൻ പ്രയാസമാകാം. ഗ്രേസ്കെയിൽ, വലിയ വലുപ്പം, അല്ലെങ്കിൽ PDF ഭാഗങ്ങളാക്കി നോക്കൂ.',
    c_method: 'രീതി',
    c_strong: 'ശക്തം: വലുപ്പത്തിലെത്തൂ',
    c_strong_d: 'ഫോമുകൾക്കും പോർട്ടലുകൾക്കും മികച്ചത്. പേജുകൾ ചിത്രങ്ങളാകും, അതിനാൽ ടെക്സ്റ്റ് സെലക്ട് ചെയ്യാനാവില്ല.',
    c_light: 'ലഘു: ടെക്സ്റ്റ് അതേപടി',
    c_light_d: 'ടെക്സ്റ്റ് സെലക്ട് ചെയ്യാനും തിരയാനും കഴിയും. ലാഭം കുറവ്, സാധാരണ 5–30%.',
    gray_opt: 'കറുപ്പും വെളുപ്പും (ഗ്രേസ്കെയിൽ): ഇനിയും ചെറുത്',
    c_go: 'PDF ചെറുതാക്കൂ',
    c_empty: 'ചെറുതാക്കിയ PDF മുൻപും ശേഷവുമുള്ള പ്രിവ്യൂവോടെ ഇവിടെ കാണാം.',
    c_ready: 'വലുപ്പം തിരഞ്ഞെടുത്ത് “PDF ചെറുതാക്കൂ” അമർത്തൂ.',
    c_already: 'സന്തോഷവാർത്ത: ഈ PDF ഇതിനകം {to}-ൽ താഴെയാണ് ({size}). ഇതേപടി അപ്‌ലോഡ് ചെയ്യാം.',
