    c_done_over: 'സാധ്യമായത്: {size}. പേജുകൾ വായിക്കാനാകാത്തവിധം ആക്കാതെ {to}-ൽ താഴെ എത്തിക്കാനായില്ല. വലിയ വലുപ്പം, ഗ്രേസ്കെയിൽ, അല്ലെങ്കിൽ PDF ഭാഗങ്ങളാക്കി നോക്കൂ.',
    c_bigger: 'ഈ PDF ഇതിനകം നന്നായി കംപ്രസ് ചെയ്തതാണ്: പുതിയ പകർപ്പ് വലുതാകും ({size}). നിങ്ങളുടെ ഒറിജിനൽ ഫയൽ തന്നെ സൂക്ഷിക്കൂ.',
    c_light_ok: 'കഴിഞ്ഞു! ടെക്സ്റ്റ് അതേപടിയുണ്ട്, ഫയൽ {to}-ൽ താഴെയാണ്.',
    c_light_over: 'ടെക്സ്റ്റ് അതേപടിയുണ്ട്, പക്ഷേ ഫയൽ ഇപ്പോഴും {to}-ൽ കൂടുതലാണ്. വലുപ്പത്തിലെത്താൻ “ശക്തം” തിരഞ്ഞെടുക്കൂ.',
    c_light_none: '“ലഘു” രീതിക്ക് ഈ PDF ചെറുതാക്കാനായില്ല. “ശക്തം” തിരഞ്ഞെടുക്കൂ.',
    c_light_locked: 'ഈ PDF ലോക്ക് ചെയ്തതിനാൽ “ലഘു” രീതിക്ക് അത് വീണ്ടും സേവ് ചെയ്യാനാവില്ല. “ശക്തം” തിരഞ്ഞെടുക്കൂ (അത് പാസ്‌വേഡ് ചോദിക്കും), അല്ലെങ്കിൽ ആദ്യം അൺലോക്ക് ചെയ്യൂ.',
    c_auto: 'ഫയൽ കുറഞ്ഞ ഇടത്തിൽ വീണ്ടും സേവ് ചെയ്താൽ മതിയായിരുന്നു, അതിനാൽ പേജുകൾ ചിത്രങ്ങളായില്ല. ടെക്സ്റ്റ് വ്യക്തമാണ്, സെലക്ട് ചെയ്യാനും കഴിയും.',
    c_low_res: 'വലുപ്പത്തിലൊതുക്കാൻ പേജുകൾ {dpi} dpi മാത്രമാണ്, അതിനാൽ ചെറിയ അക്ഷരങ്ങൾ വായിക്കാൻ പ്രയാസമാകാം. “താരതമ്യം” വഴി പരിശോധിക്കൂ; ഗ്രേസ്കെയിൽ അല്ലെങ്കിൽ വലിയ വലുപ്പം സഹായിക്കും.',
    c_before: 'മുൻപ്',
    c_after: 'ശേഷം',
    compare: 'മുൻപും ശേഷവും താരതമ്യം ചെയ്യൂ',
    cmp_hint: 'രണ്ടിനുമിടയിൽ മാറി നോക്കി, അക്ഷരങ്ങൾ ഇപ്പോഴും എളുപ്പത്തിൽ വായിക്കാമോ എന്ന് ഉറപ്പാക്കൂ.',
    c_note_raster: 'ഈ പകർപ്പിൽ ടെക്സ്റ്റ് ചിത്രത്തിന്റെ ഭാഗമാണ്, അതിനാൽ സെലക്ട് ചെയ്യാനോ തിരയാനോ കഴിയില്ല. രേഖകൾക്കായി ഒറിജിനൽ ഫയൽ സൂക്ഷിക്കൂ.',
