    u_title: 'നിങ്ങളുടെ PDF അൺലോക്ക് ചെയ്യൂ',
    u_desc: 'പാസ്‌വേഡുള്ള നിങ്ങളുടെ സ്വന്തം PDF-ന്റെ (ഇ-ആധാർ, ബാങ്ക് സ്റ്റേറ്റ്മെന്റ്, ശമ്പള സ്ലിപ്പ്) പാസ്‌വേഡില്ലാതെ തുറക്കുന്ന പകർപ്പ് സേവ് ചെയ്യൂ.',
    u_warn: 'നിങ്ങളുടെ സ്വന്തം രേഖകൾക്ക് മാത്രം. പാസ്‌വേഡ് നിങ്ങൾക്ക് അറിയണം: ഈ ടൂൾ പാസ്‌വേഡ് ഊഹിക്കുകയോ തകർക്കുകയോ ചെയ്യില്ല.',
