    u_go: 'അൺലോക്ക് ചെയ്ത പകർപ്പ് സേവ് ചെയ്യൂ',
    u_unlocked: 'നിങ്ങളുടെ പാസ്‌വേഡ് കൊണ്ട് തുറന്നു. ഇനി പാസ്‌വേഡ് വേണ്ടാത്ത പകർപ്പ് സേവ് ചെയ്യൂ.',
    u_owner: 'ഈ PDF പാസ്‌വേഡില്ലാതെ തുറക്കും, പക്ഷേ പ്രിന്റ് ചെയ്യലോ കോപ്പി ചെയ്യലോ തടഞ്ഞിരിക്കാം. ഈ നിയന്ത്രണങ്ങളില്ലാത്ത പകർപ്പ് സേവ് ചെയ്യൂ.',
    u_none: 'ഈ PDF ലോക്ക് ചെയ്തതല്ല: പാസ്‌വേഡില്ലാതെ തുറക്കും, ഒരു നിയന്ത്രണവുമില്ല.',
    u_cancel_pw: 'ഇപ്പോഴും ലോക്കിലാണ്: അൺലോക്ക് ചെയ്യാൻ പാസ്‌വേഡ് ടൈപ്പ് ചെയ്യൂ.',
    u_done: 'അൺലോക്ക് ചെയ്ത പകർപ്പ് തയ്യാർ ({pages}). ഇത് പാസ്‌വേഡില്ലാതെ തുറക്കും.',
    u_compress: 'ഈ പകർപ്പ് ചെറുതാക്കൂ',
    u_note: 'പേജുകൾ ചിത്രങ്ങളായാണ് സേവ് ചെയ്യുന്നത്, അതിനാൽ ടെക്സ്റ്റ് സെലക്ട് ചെയ്യാനാവില്ല. ഒറിജിനൽ ഫയലും സൂക്ഷിക്കൂ.',
    u_empty: 'അൺലോക്ക് ചെയ്ത പകർപ്പ് ഇവിടെ കാണാം.',
    help_title: 'എങ്ങനെ ഉപയോഗിക്കാം / ജോലിക്കുള്ള ആശയങ്ങൾ',
    tip1: 'പരീക്ഷയുടെയോ ജോലിയുടെയോ ഫോമിൽ “PDF 200 KB-ൽ താഴെ” എന്നുണ്ടോ? ഫയൽ തിരഞ്ഞെടുത്ത്, 200 KB അമർത്തി, “PDF ചെറുതാക്കൂ” അമർത്തൂ. SSC, UPSC, NEET, പാസ്‌പോർട്ട്, സ്കോളർഷിപ്പ്, GST, ആദായനികുതി പോർട്ടലുകൾക്ക് ഉപകാരപ്പെടും.',
    tip2: 'KYC-ക്കുള്ള ആധാർ അല്ലെങ്കിൽ പാൻ പകർപ്പ്: മുൻവശത്തിന്റെയും പിൻവശത്തിന്റെയും ഫോട്ടോ എടുത്ത്, “JPG-ൽ നിന്ന് PDF” തുറന്ന്, ഒരു പേജിൽ 2 ഫോട്ടോയും യഥാർഥ ID കാർഡ് വലുപ്പവും തിരഞ്ഞെടുത്ത്, PDF പ്രിന്റ് ചെയ്യൂ അല്ലെങ്കിൽ അയയ്ക്കൂ.',
    tip3: 'ഫോണിൽ എടുത്ത പേജിന്റെ ഫോട്ടോ ചാരനിറത്തിലോ നിഴലോടെയോ ആണോ? “സ്കാൻ പോലെ” (നിറം നിലനിൽക്കും) അല്ലെങ്കിൽ “കറുപ്പും വെളുപ്പും” (ഏറ്റവും വ്യക്തമായ അക്ഷരം, ഏറ്റവും ചെറിയ ഫയൽ) തിരഞ്ഞെടുക്കൂ.',
    tip4: 'WhatsApp, Instagram അല്ലെങ്കിൽ വെബ്സൈറ്റിനായി ഒരു സ്ലൈഡോ മെനു കാർഡോ സർട്ടിഫിക്കറ്റോ ചിത്രമായി വേണോ? “PDF-ൽ നിന്ന് JPG”-ൽ 150 dpi ഉപയോഗിക്കൂ; പ്രിന്റിന് 300 dpi.',
    tip5: 'ഇ-ആധാർ പാസ്‌വേഡ്: നിങ്ങളുടെ പേരിലെ ആദ്യ 4 അക്ഷരങ്ങൾ ഇംഗ്ലീഷ് ക്യാപിറ്റലിൽ + ജനന വർഷം, ഉദാ. SURE1990. ബാങ്ക് സ്റ്റേറ്റ്മെന്റുകൾക്ക് പലപ്പോഴും ജനനത്തീയതിയോ കസ്റ്റമർ ID-യോ ആണ്; ബാങ്കിന്റെ ഇമെയിലിൽ പറഞ്ഞിരിക്കും.',
    tip6: '“ശക്തം” രീതി പേജുകളെ ചിത്രങ്ങളാക്കും. രേഖകൾക്കായി ഒറിജിനൽ ഫയൽ സൂക്ഷിക്കൂ; ടെക്സ്റ്റ് തിരയാൻ കഴിയേണ്ട കരാറുകൾക്കും ഇൻവോയ്സുകൾക്കും “ലഘു” ഉപയോഗിക്കൂ.',
    inside_title: 'ഉള്ളിൽ എന്ത് നടക്കുന്നു?',
    inside_body: 'PDF.js (Mozilla നിർമിച്ചത്) ഓരോ പേജും നിങ്ങളുടെ ബ്രൗസറിനുള്ളിൽ തന്നെ വരയ്ക്കുന്നു. ഒരു വലുപ്പത്തിലെത്താൻ ആപ്പ് ചില സാമ്പിൾ പേജുകളിൽ പല വ്യക്തതയും (dpi) JPEG ക്വാളിറ്റിയും പരീക്ഷിച്ച്, ചേരുന്ന ഏറ്റവും നല്ല സെറ്റിങ് തിരഞ്ഞെടുത്ത്, pdf-lib ഉപയോഗിച്ച് പുതിയ PDF ഉണ്ടാക്കി, തുടർന്ന് അതിന്റെ യഥാർഥ വലുപ്പം പരിശോധിക്കുന്നു. ഒന്നും ഒരു സർവറിലേക്കും അയയ്ക്കുന്നില്ല.',
    settings_saved: 'നിങ്ങളുടെ സെറ്റിങ്ങുകൾ ഈ ഉപകരണത്തിൽ സേവ് ആയിരിക്കും. നിങ്ങളുടെ ഫയലുകൾ ഒരിക്കലും സേവ് ചെയ്യില്ല.'
